	/** 
	 * jumpstart the process by instantiating2 Application
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		applicationId = ApplicationService.getApplicationInstance()
		.createApplication( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		ApplicationService.getApplicationInstance()
				.createApplication( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.applicationSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Application : " + successValue.getApplicationId());
							  if (successValue.getApplicationId().equals(applicationId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfApplicationList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Application test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on application consumed")
					);
			subscriber.applicationSubscribe( applicationId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Application : " + successValue.getApplicationId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfApplicationList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on application for applicationId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Application. 
	 */
	protected Application read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Application" );

		Application entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Application with primary key" );
		msg.append( applicationId );
		
		ApplicationFetchOneSummary fetchOneSummary = new ApplicationFetchOneSummary( applicationId );

		try {
			entity = ApplicationService.getApplicationInstance().getApplication( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Application " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Application.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Application." );

		StringBuilder msg = new StringBuilder( "Failed to update a Application : " );        
		Application entity = read();
		UpdateApplicationCommand command = generateUpdateCommand();
		command.setApplicationId(entity.getApplicationId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Application." );

			// for use later on...
			applicationId = entity.getApplicationId();

			ApplicationService proxy = ApplicationService.getApplicationInstance();  

			proxy.updateApplication( command ).get();

			LOGGER.info( "-- Successfully saved Application - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + applicationId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Application.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Application." );

		Application entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Application with id " + applicationId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Application with id " + applicationId );

			throw e;
		}

		try{
			ApplicationService.getApplicationInstance().delete( new DeleteApplicationCommand( entity.getApplicationId() ) ).get();
			LOGGER.info( "-- Successfully deleted Application with id " + applicationId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Application with id " + applicationId );

			throw e;
		}
	}

	/**
	 * get all Applications.
	 */
	protected List<Application> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Applications:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Application : " );        
		List<Application> collection  = new ArrayList<>();

		try {
			// call the static get method on the ApplicationService
			collection = ApplicationService.getApplicationInstance().getAllApplication();
			assertNotNull( collection, "An Empty collection of Application was incorrectly returned.");
			
			// Now print out the values
			Application entity = null;            
			Iterator<Application> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getApplicationId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

